function V=run_g2_wp2_verification_batch()
%RUN_G2_WP2_VERIFICATION_BATCH  WP2 preregistered tests S1, S2, M1-M4 (WP2_PREREGISTRATION.md).
% Uses the isolated frozen p010 block (2,788 + 128 T3, regenerated by the PR #19
% code) as the domain for the solver patch test and the manufactured Williams
% problems. Writes a NEW outputs/g2_wp2_verification/run_* folder. Tolerances are
% the preregistered ones and are not changed here.
here=fileparts(mfilename('fullpath'));repo=fileparts(fileparts(here));
vendor=fullfile(here,'vendor_p010_a14d8872');addpath(vendor,'-begin');
assert(strcmpi(which('T3toT6_fast'),fullfile(vendor,'T3toT6_fast.m')),'G2V:Vendor','Vendor shadowed.');
outRoot=fullfile(repo,'outputs','g2_wp2_verification');if ~exist(outRoot,'dir'),mkdir(outRoot);end
folder=fullfile(outRoot,['run_',datestr(now,'yyyymmdd_HHMMSS_FFF')]);assert(~exist(folder,'dir'));mkdir(folder);
diary(fullfile(folder,'verification_console.log'));c=onCleanup(@()diary('off')); %#ok<NASGU>
fprintf('STAGE=G2_WP2_VERIFICATION_S_M\nDATE=%s\nMATLAB_RELEASE=%s\nOUTDIR=%s\n',datestr(now,31),version('-release'),folder);
TOL=struct('S1stress',1e-9,'S1rigid',1e-12,'S2',1e-6,'M1edi',.010,'M1cod',.030,'M2',.005,'M3',.005,'M4',.001);
V=struct('pass',false,'tolerances',TOL,'tests',struct(),'exception','');
try
 B=g2_p010_cornell_regular_block('Plot',false);assert(B.pass,'G2V:Block','p010 block HOLD.');
 X6=B.coord6;T6=B.connect6;tip=B.summary.tip_mm;tdir=[0 1];
 mat=struct('E',3268.115,'nu',.35,'plane','stress');
 bnd=boundary_nodes(T6);
 L=[(X6(:,1)-tip(1))*0+(X6(:,2)-tip(2)),-(X6(:,1)-tip(1))];   % x1 = t.(x-tip), x2 = n.(x-tip), t=(0,1), n=(-1,0)
 onFace=abs(L(:,2))<1e-9&L(:,1)<1e-9;
 rimN=bnd(~onFace(bnd));
 % ---------------- S1: patch test (linear field on the whole boundary) + rigid modes
 Bm=[1e-3 -4e-4;2.5e-4 -7e-4];a0=[.01 -.02];
 ulin=@(P)[a0(1)+P*Bm(1,:).',a0(2)+P*Bm(2,:).'];
 Ub=ulin(X6(bnd,:));
 bc=struct('fixedDofs',[2*bnd-1;2*bnd],'fixedValues',[Ub(:,1);Ub(:,2)],'F',zeros(2*size(X6,1),1));
 S=g2_t6_elasticity(X6,T6,mat,bc);
 Uex=ulin(X6);ue=reshape([Uex(:,1).';Uex(:,2).'],[],1);
 eps0=[Bm(1,1),Bm(2,2),Bm(1,2)+Bm(2,1)];sig0=S.D*eps0(:);
 G=elem_grad(X6,T6,S.u);sig=[S.D(1,1)*G(:,1)+S.D(1,2)*G(:,4),S.D(1,2)*G(:,1)+S.D(2,2)*G(:,4),S.D(3,3)*(G(:,2)+G(:,3))];
 s1err=max(max(abs(sig-sig0.')))/norm(sig0);
 uerr=max(abs(S.u-ue))/max(abs(ue));
 rig=[ones(size(X6,1),1),zeros(size(X6,1),1);zeros(size(X6,1),1),ones(size(X6,1),1);-X6(:,2),X6(:,1)];
 nn=size(X6,1);rigE=zeros(3,1);
 for k=1:3,v=reshape([rig((k-1)*nn+(1:nn),1).';rig((k-1)*nn+(1:nn),2).'],[],1);rigE(k)=abs(v.'*S.K*v)/(norm(S.K,1)*norm(v)^2);end
 V.tests.S1=struct('maxStressError_rel',s1err,'maxDisplacementError_rel',uerr,'rigidModeEnergy_rel',rigE.', ...
   'pass',s1err<=TOL.S1stress&&max(rigE)<=TOL.S1rigid);
 fprintf('S1 patch: stress err %.3e, u err %.3e, rigid %.3e -> %d\n',s1err,uerr,max(rigE),V.tests.S1.pass);
 % ---------------- S2: Williams field self-consistency
 rng(20261118);np=400;rr=.05+2.95*rand(np,1);th=(2*rand(np,1)-1)*pi*.999;
 x1=rr.*cos(th);x2=rr.*sin(th);s2=0;fd=0;
 for pl={'stress','strain'}
  m2=mat;m2.plane=pl{1};[D2,~,kap,mu]=g2_plane_D(m2);
  for k=1:4
   KI=randn;KII=randn;T=randn*.2;W=g2_williams_field(x1,x2,KI,KII,T,mu,kap);
   e12=.5*(W.G12+W.G21);sh=[D2(1,1)*W.G11+D2(1,2)*W.G22,D2(1,2)*W.G11+D2(2,2)*W.G22,D2(3,3)*2*e12];
   ref=max(abs([W.s11;W.s22;W.s12]));
   s2=max(s2,max(max(abs(sh-[W.s11,W.s22,W.s12])))/ref);
   h=1e-6;Wp=g2_williams_field(x1+h,x2,KI,KII,T,mu,kap);Wm=g2_williams_field(x1-h,x2,KI,KII,T,mu,kap);
   Wq=g2_williams_field(x1,x2+h,KI,KII,T,mu,kap);Wr=g2_williams_field(x1,x2-h,KI,KII,T,mu,kap);
   fdG=[(Wp.u1-Wm.u1)/(2*h),(Wq.u1-Wr.u1)/(2*h),(Wp.u2-Wm.u2)/(2*h),(Wq.u2-Wr.u2)/(2*h)];
   Ga=[W.G11,W.G12,W.G21,W.G22];fd=max(fd,max(max(abs(fdG-Ga)))/max(abs(Ga(:))));
  end
 end
 V.tests.S2=struct('hookeVsStress_rel',s2,'finiteDifferenceVsGradient_rel',fd,'pass',s2<=TOL.S2&&fd<=TOL.S2);
 fprintf('S2 Williams: Hooke %.3e, FD %.3e -> %d\n',s2,fd,V.tests.S2.pass);
 % ---------------- M1-M4: manufactured Williams fields on the rim
 [~,Ep,kap,mu]=g2_plane_D(mat);
 cases=[1 0 0;0 1 0;.6 -.8 0;1 0 .2;0 1 .2;.6 -.8 -.2];
 annuli=[.4 2.6;.2 1.0;.4 1.6;.8 2.6;1.2 2.4];
 rows={};allOK=true;
 for k=1:size(cases,1)
  KI=cases(k,1);KII=cases(k,2);T=cases(k,3);Kref=hypot(KI,KII);
  P=X6(rimN,:)-tip;W=g2_williams_field(P*[0;1],P*[-1;0],KI,KII,T,mu,kap);
  ug=W.u1*[0 1]+W.u2*[-1 0];
  bc=struct('fixedDofs',[2*rimN-1;2*rimN],'fixedValues',[ug(:,1);ug(:,2)],'F',zeros(2*size(X6,1),1));
  S=g2_t6_elasticity(X6,T6,mat,bc);
  ed=zeros(size(annuli,1),3);
  for j=1:size(annuli,1)
   Rj=g2_sif_interaction(X6,T6,S.u,mat,tip,tdir,annuli(j,1),annuli(j,2),6);ed(j,:)=[Rj.KI,Rj.KII,Rj.J];
  end
  R4=g2_sif_interaction(X6,T6,S.u,mat,tip,tdir,.4,2.6,4);
  C=g2_sif_cod(X6,T6,S.u,mat,tip,tdir,[.1 1.5]);
  eEDI=max(abs(ed(1,1:2)-[KI KII]))/Kref;eCOD=max(abs([C.KI C.KII]-[KI KII]))/Kref;
  spread=max(max(ed(:,1:2))-min(ed(:,1:2)))/Kref;
  eJ=abs(ed(1,3)/((ed(1,1)^2+ed(1,2)^2)/Ep)-1);
  eQ=max(abs([R4.KI R4.KII]-ed(1,1:2)))/Kref;
  signOK=(KII==0)||sign(ed(1,2))==sign(KII)&&sign(C.KII)==sign(KII);
  ok=eEDI<=TOL.M1edi&&eCOD<=TOL.M1cod&&spread<=TOL.M2&&eJ<=TOL.M3&&eQ<=TOL.M4&&signOK;
  allOK=allOK&&ok;
  rows(end+1,:)={KI,KII,T,ed(1,1),ed(1,2),C.KI,C.KII,eEDI,eCOD,spread,eJ,eQ,signOK,ok}; %#ok<AGROW>
  fprintf('M case (%.1f,%.1f,T=%.1f): EDI (%.6f,%.6f) err %.3e | COD (%.6f,%.6f) err %.3e | spread %.3e | J %.3e | quad %.3e -> %d\n', ...
   KI,KII,T,ed(1,1),ed(1,2),eEDI,C.KI,C.KII,eCOD,spread,eJ,eQ,ok);
  if k==3,save(fullfile(folder,'M1_mixed_case_annuli.mat'),'ed','annuli','C');end
 end
 Tm=cell2table(rows,'VariableNames',{'KI','KII','T','KI_EDI','KII_EDI','KI_COD','KII_COD','errEDI','errCOD','pathSpread','energyErr','quadErr','signOK','pass'});
 writetable(Tm,fullfile(folder,'M1_M4_manufactured.csv'));disp(Tm);
 V.tests.M=table2struct(Tm);V.tests.Mpass=allOK;
 V.pass=V.tests.S1.pass&&V.tests.S2.pass&&allOK;
catch ME
 V.exception=getReport(ME,'extended','hyperlinks','off');fprintf(2,'G2_WP2_VERIFICATION_EXCEPTION=%s\n',V.exception);
end
f=fopen(fullfile(folder,'wp2_verification_summary.json'),'w');fwrite(f,jsonencode(V,'PrettyPrint',true),'char');fclose(f);
fprintf('G2_WP2_VERIFICATION_S_M_PASS=%d\n',V.pass);
if ~V.pass,error('G2V:HOLD','WP2 S/M verification HOLD (see %s).',folder);end
end

function b=boundary_nodes(T6)
E3=[T6(:,[1 2 4]);T6(:,[2 3 5]);T6(:,[3 1 6])];
[~,~,ic]=unique(sort(E3(:,1:2),2),'rows');cnt=accumarray(ic,1);
b=unique(reshape(E3(cnt(ic)==1,:),[],1));
end

function G=elem_grad(X6,T6,u)
% displacement gradient at each element centroid [du/dx du/dy dv/dx dv/dy]
M=size(T6,1);x=reshape(X6(T6(:),1),M,6);y=reshape(X6(T6(:),2),M,6);
U=reshape(u(2*T6(:)-1),M,6);Vv=reshape(u(2*T6(:)),M,6);
J11=x(:,2)-x(:,1);J12=x(:,3)-x(:,1);J21=y(:,2)-y(:,1);J22=y(:,3)-y(:,1);d=J11.*J22-J12.*J21;
r=1/3;s=1/3;t=1/3;dNr=[-(4*t-1),4*r-1,0,4*(t-r),4*s,-4*s];dNs=[-(4*t-1),0,4*s-1,-4*r,4*r,4*(t-s)];
Nx=(J22*dNr-J21*dNs)./d;Ny=(-J12*dNr+J11*dNs)./d;
G=[sum(Nx.*U,2),sum(Ny.*U,2),sum(Nx.*Vv,2),sum(Ny.*Vv,2)];
end
